DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.operation_action(uuid,text,jsonb)'::regprocedure) INTO def; def:=replace(def,'jsonb_build_object(''side'',CASE WHEN s THEN ''seller'' ELSE ''buyer'' END)','jsonb_build_object(''side'',CASE WHEN s THEN ''seller'' ELSE ''buyer'' END,''version'',o.version)');def:=replace(def,'IF NOT FOUND OR NOT ((s AND r.data','IF NOT FOUND OR (r.data->>''version'')::integer IS DISTINCT FROM o.version OR NOT ((s AND r.data');EXECUTE def;END $$;